/usr/bin/bash -lc "/opt/conda/bin/python - <<'PY'
import json
p='run_trace/analysis_steps.jsonl'
with open(p) as f:
    for i,line in enumerate(f,1):
        try: json.loads(line)
        except Exception as e: print('bad line',i,e)
print('lines parsed ok')
PY
wc -l run_trace/analysis_steps.jsonl; head -2 final_answer/verified_peptides.tsv; tail -3 final_answer/verified_peptides.tsv"

